请对以下 case 进行三维加权评分。

=== case_id ===
Case-17-queue-326

=== 用户原始指令 (query.txt) ===
整个叫号卡吧 有个背景图 文字叠上面 数字会变 点一下进app 还剩几个红色危险提示

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "整个叫号卡吧 有个背景图 文字叠上面 数字会变 点一下进app 还剩几个红色危险提示",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.example.queue",
        "abilityName": "com.example.queue.MainAbility",
        "uri": "queue://ticket/current"
      }
    }
  ],
  "dataModel": {
    "value": {
      "queue": {
        "title": "取号进度",
        "currentNumber": "A086",
        "remainingText": "前方还剩 3 位",
        "alertText": "即将叫到，请留意",
        "actionLabel": "进入排队",
        "icon": "assets/queue-ticket.png"
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "queue_ticket_icon",
      "src": "assets/queue-ticket.png",
      "use": "queue ticket icon",
      "description": "排队叫号票据图标，用作叫号卡背景层上的识别素材。",
      "bindTo": "/queue/icon",
      "static": true
    }
  ]
}

